#!/usr/bin/env python3
"""Issue #419 design prototype: derive the prototype and mutant sources.

Every output is produced from a TRACKED source by counted, exact textual
replacement, so a reviewer can re-derive each file and diff it. Nothing under
the repository's tracked tree is written; all outputs land beside this script.

Usage: python3 -B proposal-evidence/mkproto.py --root <checkout>
"""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent

RTL = "hdl/milan/KL_nvm_backend.sv"
FW = "sw/firmware/milan_baremetal/milan_baremetal.c"

#: the tracked bytes this prototype is derived from, as published on #418
PRISTINE = {
    RTL: "1362b5a9d6f7feab5d80f0bc54b6f76342bd239f2fed6f94590706d0b18c3e68",
    FW: "3c28591f76afad67eebd77ed185a021e3a2bcdff5c3f7650d7a1e0374ab77b41",
    "sw/firmware/nvm_hosttest/nvm_host.c":
        "efbc5d5c494ccb86127019d48fba41ede3655ff27c329b56dc6d1f30cac07450",
}


def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def once(text: str, old: str, new: str, what: str) -> str:
    """Replace `old` exactly once, or refuse."""
    n = text.count(old)
    if n != 1:
        raise SystemExit(f"seam {what!r} occurs {n} times, expected 1")
    return text.replace(old, new, 1)


# --------------------------------------------------------------------------
#  The backend: the capture window and the record-gap interlock
# --------------------------------------------------------------------------
RTL_EDITS = [
    ("banner", """//  Refusals    : an unallocated record_id, a span past the record, a span""",
     """//  #419 PROTOTYPE: this file is NOT tracked RTL. It is the shipping module
//                with the section 9 acknowledgement contract replaced by the
//                capture-window contract proposed on issue #419: an ARM
//                strobe opens a window, any image mutation inside it voids
//                the window, and an acknowledgement retires dirty only while
//                the window is intact. A record whose span an ERASE has
//                blanked and no WRITE has closed is a GAP: the window cannot
//                be opened over one, so a mid-update blank span is never
//                sealed as a new saved state. Everything else, including the
//                byte pump, the region decode and the deadlines, is the
//                tracked module unchanged.
//
//  Refusals    : an unallocated record_id, a span past the record, a span"""),

    ("declarations", """  logic        backed_r, dirty_r, stale_r, ever_backed_r;
  logic        reg_we_w, hb_kick_w, commit_ack_w, commit_start_w;
  logic        img_cfg_w, img_live_w, write_commit_w, dirty_set_w;
""",
     """  logic        backed_r, dirty_r, stale_r, ever_backed_r;
  logic        reg_we_w, hb_kick_w, commit_ack_w, commit_start_w;
  logic        img_cfg_w, img_live_w, write_commit_w, dirty_set_w;
  //! ---- #419: the capture window and the record-gap interlock ----------
  //! cap_armed_r  a window is open: the firmware asked for one and has not
  //!              acknowledged yet. Cleared by ANY acknowledgement, so a
  //!              repeated one finds no window and retires nothing.
  //! cap_valid_r  nothing has mutated the image since the window opened.
  //! ack_ref_r    the last acknowledgement inside this window was refused;
  //!              published so the firmware knows the commit did not retire
  //!              the change rather than inferring it from a status level.
  //! gap_open_r   an ERASE has blanked a record span and no WRITE has closed
  //!              it. The image is not a completed-record state.
  //! gap_stuck_r  a second span was blanked while one was already open, so
  //!              the single-entry tracker can no longer name the blank
  //!              spans. Fail safe: no window may be opened until reset.
  logic        cap_arm_w, cap_rel_w, cap_armed_r, cap_valid_r, ack_ref_r;
  logic        cap_block_w, ack_ok_w, erase_commit_w, mut_w, gap_w;
  logic        gap_open_r, gap_stuck_r, was_erase_r;
  logic [7:0]  gap_region_r, op_region_r;
  //! a feature probe in the status word's top byte, the house pattern: a
  //! build without this contract reads 0 there and the firmware refuses to
  //! persist rather than silently using the old acknowledgement rule
  localparam logic [7:0] CAP_TAG_C = 8'hCA;
"""),

    ("arm strobe", """  assign commit_start_w = reg_we_w & (csr_addr_i[4:0] == R_ACK_C) & csr_wdata_i[2];
""",
     """  assign commit_start_w = reg_we_w & (csr_addr_i[4:0] == R_ACK_C) & csr_wdata_i[2];
  //! #419: [3] opens a capture window. A strobe, never a level, and never a
  //! knob: it cannot make an image durable, only mark the point after which
  //! a mutation voids the acknowledgement. [4] RELEASES an attempt that will
  //! not be acknowledged: it closes the window and the commit bracket and
  //! retires nothing, so an abandoned commit costs one debounce rather than
  //! the whole commit deadline and a durability claim nobody lost.
  assign cap_arm_w      = reg_we_w & (csr_addr_i[4:0] == R_ACK_C) & csr_wdata_i[3];
  assign cap_rel_w      = reg_we_w & (csr_addr_i[4:0] == R_ACK_C) & csr_wdata_i[4];
"""),

    ("status word", """        R_STAT_C:     csr_rdata_o = {16'd0, verdict_r, 1'b0, commit_busy_r,
                                     nvm_stale_o, dirty_r, img_valid_r,
                                     backed_r, img_cfg_w, dev_busy_w, 4'd0};""",
     """        R_STAT_C:     csr_rdata_o = {CAP_TAG_C, 4'd0,
                                     ack_ref_r, gap_w, cap_valid_r, cap_armed_r,
                                     verdict_r, 1'b0, commit_busy_r,
                                     nvm_stale_o, dirty_r, img_valid_r,
                                     backed_r, img_cfg_w, dev_busy_w, 4'd0};"""),

    ("commit bracket", """      if (commit_start_w) begin
        commit_r      <= 16'(T_COMMIT_MS_P);
        commit_busy_r <= 1'b1;
      end else if (commit_ack_w) begin
        commit_busy_r <= 1'b0;
      end else if (commit_busy_r && ms_tick_w && (commit_r != 16'd0)) begin""",
     """      if (commit_start_w) begin
        commit_r      <= 16'(T_COMMIT_MS_P);
        commit_busy_r <= 1'b1;
      end else if (commit_ack_w || cap_rel_w) begin
        //! #419: a released attempt closes the bracket at once. Waiting for
        //! the deadline would block the retry for the whole timeout and then
        //! revoke a durability claim no writer had actually lost.
        commit_busy_r <= 1'b0;
      end else if (commit_busy_r && ms_tick_w && (commit_r != 16'd0)) begin"""),

    ("commit deadline guard", """  assign commit_exp_w = commit_busy_r & ms_tick_w & (commit_r == 16'd1)
                        & ~commit_start_w & ~commit_ack_w;""",
     """  assign commit_exp_w = commit_busy_r & ms_tick_w & (commit_r == 16'd1)
                        & ~commit_start_w & ~commit_ack_w & ~cap_rel_w;"""),

    ("dirty next state", """  assign dirty_set_w = change_i | write_commit_w;
  assign dirty_n_w   = dirty_set_w  ? 1'b1
                     : commit_ack_w ? 1'b0
                                    : dirty_r;
""",
     """  //! #419: a completed ERASE mutates the image exactly as a completed WRITE
  //! does -- it replaces a record with 0xFF -- so it marks the image dirty
  //! and voids an open window. Leaving it out is what let a blank span be
  //! published as (backed=1, dirty=0) over a record the producer was in the
  //! middle of rewriting.
  assign erase_commit_w = done_r & was_erase_r;
  assign mut_w          = change_i | write_commit_w | erase_commit_w;
  assign gap_w          = gap_open_r | gap_stuck_r;
  //! a window may not be opened over an operation in flight or over a blank
  //! span the producer has not closed
  assign cap_block_w    = dev_busy_w | gap_w;
  //! PRIORITY, and it is the whole repair: a mutation ANYWHERE in the window
  //! wins over the acknowledgement, not only one on its exact edge.
  assign ack_ok_w       = commit_ack_w & cap_armed_r & cap_valid_r & ~mut_w;
  assign dirty_set_w    = mut_w;
  assign dirty_n_w      = dirty_set_w ? 1'b1
                        : ack_ok_w    ? 1'b0
                                      : dirty_r;
"""),

    ("status reset", """      backed_r      <= 1'b0;
      dirty_r       <= 1'b0;
      stale_r       <= 1'b0;
      ever_backed_r <= 1'b0;
    end else begin""",
     """      backed_r      <= 1'b0;
      dirty_r       <= 1'b0;
      stale_r       <= 1'b0;
      ever_backed_r <= 1'b0;
      cap_armed_r   <= 1'b0;
      cap_valid_r   <= 1'b0;
      ack_ref_r     <= 1'b0;
      gap_open_r    <= 1'b0;
      gap_stuck_r   <= 1'b0;
      gap_region_r  <= 8'd0;
    end else begin"""),

    ("status sequential", """      backed_r <= backed_n_w;
      dirty_r  <= dirty_n_w;
      stale_r  <= stale_n_w;
    end
  end""",
     """      backed_r <= backed_n_w;
      dirty_r  <= dirty_n_w;
      stale_r  <= stale_n_w;

      //! #419 the window. An arm opens it; the arm itself refuses when the
      //! image is not a completed-record state or when the arming edge is
      //! also a mutation. Any acknowledgement closes it, refused or not, and
      //! so does a release.
      cap_armed_r <= cap_arm_w                  ? 1'b1
                   : (commit_ack_w | cap_rel_w) ? 1'b0
                                                : cap_armed_r;
      cap_valid_r <= cap_arm_w ? (~cap_block_w & ~mut_w)
                               : (cap_valid_r & ~mut_w);
      ack_ref_r   <= cap_arm_w                    ? 1'b0
                   : (commit_ack_w & ~ack_ok_w)   ? 1'b1
                                                  : ack_ref_r;

      //! #419 the gap. One entry, which is exact while the initiator keeps
      //! one operation outstanding (the port's F02.8 rule); a second blanked
      //! span while one is open is unreachable there and latches fail-safe.
      if (erase_commit_w) begin
        if (gap_open_r && (gap_region_r != op_region_r)) gap_stuck_r <= 1'b1;
        gap_open_r   <= 1'b1;
        gap_region_r <= op_region_r;
      end else if (write_commit_w && gap_open_r
                   && (op_region_r == gap_region_r)) begin
        gap_open_r <= 1'b0;
      end
    end
  end"""),

    ("pump reset","""      was_write_r <= 1'b0;""",
     """      was_write_r <= 1'b0;
      was_erase_r <= 1'b0;
      op_region_r <= 8'd0;"""),

    ("pump grant", """            was_write_r <= (dev_op_i == OP_WRITE_C);""",
     """            was_write_r <= (dev_op_i == OP_WRITE_C);
            //! #419: an ERASE only blanks a span when there IS an image, the
            //! span is legal and it is not empty. The discard and refusal
            //! arms below leave the image untouched, so they open no gap.
            was_erase_r <= (dev_op_i == OP_ERASE_C) && img_cfg_w && span_ok_w
                           && (eff_len_w != 16'd0);
            op_region_r <= dev_region_i;"""),
]

#: one defect per mutant, planted in the PROTOTYPE, each expected to redden
MUTANTS = {
    "M1_window_never_voids": (
        """      cap_valid_r <= cap_arm_w ? (~cap_block_w & ~mut_w)
                               : (cap_valid_r & ~mut_w);""",
        """      cap_valid_r <= cap_arm_w ? (~cap_block_w & ~mut_w)
                               : cap_valid_r;"""),
    "M2_ack_unqualified": (
        """  assign ack_ok_w       = commit_ack_w & cap_armed_r & cap_valid_r & ~mut_w;""",
        """  assign ack_ok_w       = commit_ack_w;"""),
    "M3_arm_ignores_gap": (
        """  assign cap_block_w    = dev_busy_w | gap_w;""",
        """  assign cap_block_w    = dev_busy_w;"""),
    "M4_erase_not_a_mutation": (
        """  assign mut_w          = change_i | write_commit_w | erase_commit_w;""",
        """  assign mut_w          = change_i | write_commit_w;"""),
    "M5_window_outlives_ack": (
        """      cap_armed_r <= cap_arm_w                  ? 1'b1
                   : (commit_ack_w | cap_rel_w) ? 1'b0
                                                : cap_armed_r;""",
        """      cap_armed_r <= cap_arm_w                  ? 1'b1
                   : cap_rel_w                  ? 1'b0
                                                : cap_armed_r;"""),
    "M6_same_edge_change_loses": (
        """  assign ack_ok_w       = commit_ack_w & cap_armed_r & cap_valid_r & ~mut_w;""",
        """  assign ack_ok_w       = commit_ack_w & cap_armed_r & cap_valid_r;"""),
}


# --------------------------------------------------------------------------
#  The firmware: where the window is opened, and what a refusal means
# --------------------------------------------------------------------------
FW_EDITS = [
    ("verdict codes", """#define VD_VERIFY     13u
#define VD_COUNT      14u""",
     """#define VD_VERIFY     13u
/* #419: the producer left a record span blank and did not close it. Not a
 * container verdict: like VD_ERASE/VD_PROGRAM/VD_VERIFY it names a stage at
 * which persistence stopped, and it is published rather than acknowledged. */
#define VD_GAP        14u
#define VD_COUNT      15u"""),

    ("verdict names", """	"VD_REC", "VD_STALE", "VD_BLANK", "VD_INCOMPLETE", "VD_ERASE",
	"VD_PROGRAM", "VD_VERIFY",
};""",
     """	"VD_REC", "VD_STALE", "VD_BLANK", "VD_INCOMPLETE", "VD_ERASE",
	"VD_PROGRAM", "VD_VERIFY", "VD_GAP",
};"""),

    ("strobe and status bits", """#define NVM_STROBE_START 0x4u""",
     """#define NVM_STROBE_START 0x4u
/* #419: open a capture window before the first image byte is read. */
#define NVM_STROBE_ARM   0x8u
/* #419: this attempt will not be acknowledged; close the window and the
 * commit bracket and retire nothing. */
#define NVM_STROBE_REL   0x10u
#define NVM_RD_CAP_ARMED (1u << 16)
#define NVM_RD_CAP_VALID (1u << 17)
#define NVM_RD_CAP_GAP   (1u << 18)
#define NVM_RD_ACK_REF   (1u << 19)
#define NVM_CAP_TAG      0xcau
/* A span the producer blanked and did not close is not a completed-record
 * state. The transition itself is a handful of core clocks; the bound below
 * is the donor's own commit debounce (DEB_TICKS_P = 500 at a 1 ms tick), so
 * a gap that outlives it cannot be a normal ERASE-to-WRITE transition. */
#define NVM_GAP_TIMEOUT_NS NVM_MS(500)"""),

    ("counters", """static uint64_t nvm_dirty_since;""",
     """static uint64_t nvm_dirty_since;
static uint64_t nvm_gap_since;
static int nvm_gap_reported;
static int nvm_preerased;
static unsigned int nvm_acks_refused;"""),

    ("commit banner", """ * The A/B promotion of section 7: seal the staged image under the next
 * sequence, refuse to open a commit bracket over a torn record area, then
 * erase, program and read back the slot that is NOT authoritative. Only a
 * verified slot is acknowledged; a failure publishes its transaction verdict
 * and withholds the acknowledgement, so the commit deadline revokes the
 * durability claim instead of this firmware asserting one.
 */""",
     """ * The A/B promotion of section 7: seal the staged image under the next
 * sequence, refuse to open a commit bracket over a torn record area, then
 * erase, program and read back the slot that is NOT authoritative. Only a
 * verified slot is acknowledged; a failure publishes its transaction verdict
 * and withholds the acknowledgement, so the commit deadline revokes the
 * durability claim instead of this firmware asserting one.
 *
 * #419: the acknowledgement now identifies an image. A capture window is
 * opened BEFORE the seal, because the seal and the validate already read the
 * live record area and an acknowledgement that covered only the bytes after
 * the existing start strobe would cover neither. The window is closed by the
 * acknowledgement, and the backend retires the change only if nothing
 * mutated the image in between. A verified slot is promoted either way: it
 * is a complete image whose digest closes, and refusing to promote it would
 * throw away a good newer generation to punish a race.
 */"""),

    ("commit head", """	uint32_t next = nvm_seq + 1u;
	uint32_t target = (nvm_auth_slot == NVM_SLOT_A) ? NVM_SLOT_B : NVM_SLOT_A;
	unsigned int vd;

	nvm_in_commit = 1;
	nvm_write_header(next);""",
     """	uint32_t next = nvm_seq + 1u;
	uint32_t target = (nvm_auth_slot == NVM_SLOT_A) ? NVM_SLOT_B : NVM_SLOT_A;
	unsigned int vd;
	uint32_t stat;

	nvm_in_commit = 1;
	/* Open the window, then prove it is open. The read-back is an
	 * ORDERING device only: it puts the strobe ahead of every load this
	 * function makes. What makes the acknowledgement identify an image is
	 * the backend's one-cycle rule, not the number of status reads. */
	milan_write(MILAN_PP_NVM_STAT, NVM_STROBE_ARM);
	stat = milan_read(MILAN_PP_NVM_STAT);
	if (((stat >> 24) & 0xffu) != NVM_CAP_TAG) {
		printf("Milan NVM: this gateware has no capture window; persistence is off.\\n");
		nvm_ready = 0;
		nvm_in_commit = 0;
		return 0;
	}
	if (!(stat & NVM_RD_CAP_ARMED) || !(stat & NVM_RD_CAP_VALID)) {
		printf("Milan NVM: commit (%s) deferred, the image is mid-update%s.\\n",
		       why, (stat & NVM_RD_CAP_GAP) ? " (a record span is blank)" : "");
		milan_write(MILAN_PP_NVM_STAT, NVM_STROBE_REL);
		nvm_dirty_since = 0;
		nvm_in_commit = 0;
		return 0;
	}
	nvm_write_header(next);"""),

    ("pre-flash recheck", """	milan_write(MILAN_PP_NVM_STAT, NVM_STROBE_START);
	if (!nvm_slot_erase(target))
		vd = VD_ERASE;""",
     """	/* Cheap: do not spend an erase cycle on a window already lost. */
	if (!(milan_read(MILAN_PP_NVM_STAT) & NVM_RD_CAP_VALID)) {
		printf("Milan NVM: commit (%s) deferred, the image moved while it was sealed.\\n",
		       why);
		milan_write(MILAN_PP_NVM_STAT, NVM_STROBE_REL);
		nvm_dirty_since = 0;
		nvm_in_commit = 0;
		return 0;
	}
	milan_write(MILAN_PP_NVM_STAT, NVM_STROBE_START);
	/* An already-blank target needs no erase: the slot that is not
	 * authoritative may be erased at any time, and doing it outside the
	 * window is what keeps the window short (see nvm_preerase). */
	if (!nvm_all_erased(nvm_slot(target), NVM_IMG_LEN) && !nvm_slot_erase(target))
		vd = VD_ERASE;"""),

    ("staged deferral", """		printf("Milan NVM: commit (%s) deferred, the staged image reads %s.\\n",
		       why, nvm_verdict_name[vd]);
		nvm_dirty_since = 0;""",
     """		printf("Milan NVM: commit (%s) deferred, the staged image reads %s.\\n",
		       why, nvm_verdict_name[vd]);
		milan_write(MILAN_PP_NVM_STAT, NVM_STROBE_REL);
		nvm_dirty_since = 0;"""),

    ("failed transaction", """		nvm_csr_write(NVM_W_STAT, NVM_STAT_VALID | vd);
		nvm_commits_failed++;
		printf("Milan NVM: commit (%s) seq %lu to slot %c FAILED: %s; not acknowledged.\\n",""",
     """		nvm_csr_write(NVM_W_STAT, NVM_STAT_VALID | vd);
		milan_write(MILAN_PP_NVM_STAT, NVM_STROBE_REL);
		nvm_commits_failed++;
		printf("Milan NVM: commit (%s) seq %lu to slot %c FAILED: %s; not acknowledged.\\n",""" ),

    ("ack and report", """	nvm_seq = next;
	nvm_auth_slot = target;
	nvm_csr_write(NVM_W_SEQ, next);
	nvm_csr_write(NVM_W_STAT, NVM_STAT_VALID | VD_OK);
	milan_write(MILAN_PP_NVM_STAT, NVM_STROBE_ACK);
	nvm_commits_ok++;
	printf("Milan NVM: commit (%s) seq %lu -> slot %c, %u B, acknowledged.\\n",
	       why, (unsigned long)next, nvm_slot_letter(target),
	       (unsigned int)NVM_IMG_LEN);
	return 1;""",
     """	nvm_seq = next;
	nvm_auth_slot = target;
	nvm_preerased = 0;
	nvm_csr_write(NVM_W_SEQ, next);
	nvm_csr_write(NVM_W_STAT, NVM_STAT_VALID | VD_OK);
	milan_write(MILAN_PP_NVM_STAT, NVM_STROBE_ACK);
	nvm_commits_ok++;
	stat = milan_read(MILAN_PP_NVM_STAT);
	if (stat & NVM_RD_ACK_REF) {
		/* The slot is verified and is promoted, but it does not hold the
		 * newest record: the backend kept the change pending and the
		 * next service call commits it. */
		nvm_acks_refused++;
		printf("Milan NVM: commit (%s) seq %lu -> slot %c, %u B, verified; NOT acknowledged, the image moved.\\n",
		       why, (unsigned long)next, nvm_slot_letter(target),
		       (unsigned int)NVM_IMG_LEN);
		return 0;
	}
	printf("Milan NVM: commit (%s) seq %lu -> slot %c, %u B, acknowledged.\\n",
	       why, (unsigned long)next, nvm_slot_letter(target),
	       (unsigned int)NVM_IMG_LEN);
	return 1;"""),

    ("service", """	nvm_heartbeat_tick();
	if (!nvm_ready || nvm_in_commit)
		return;
	stat = milan_read(MILAN_PP_NVM_STAT);
	if (!(stat & NVM_RD_DIRTY)) {
		nvm_dirty_since = 0;
		return;
	}
	if (stat & (NVM_RD_DEV_BUSY | NVM_RD_COMMIT_BUSY))
		return;
	now = gettime_ns();
	if (nvm_dirty_since == 0 || now < nvm_dirty_since) {
		nvm_dirty_since = now;
		return;
	}
	if (now - nvm_dirty_since >= NVM_DEBOUNCE_NS)
		nvm_commit("dirty");""",
     """	nvm_heartbeat_tick();
	if (!nvm_ready || nvm_in_commit)
		return;
	stat = milan_read(MILAN_PP_NVM_STAT);
	now = gettime_ns();
	/* #419: a blank span the producer has not closed is not a state to
	 * save. Hold the commit and keep the last verified slot; say so once
	 * when the wait outlives anything the producer's own retry can
	 * explain, so a stalled producer is loud rather than silent. */
	if (stat & NVM_RD_CAP_GAP) {
		if (nvm_gap_since == 0 || now < nvm_gap_since) {
			nvm_gap_since = now;
		} else if (!nvm_gap_reported &&
			   now - nvm_gap_since >= NVM_GAP_TIMEOUT_NS) {
			nvm_gap_reported = 1;
			nvm_last_verdict = VD_GAP;
			nvm_csr_write(NVM_W_STAT, NVM_STAT_VALID | VD_GAP);
			printf("Milan NVM: a record span has been blank for %lu ms; persistence is held and the last verified slot stands.\\n",
			       (unsigned long)((now - nvm_gap_since) / 1000000ull));
		}
		return;
	}
	nvm_gap_since = 0;
	nvm_gap_reported = 0;
	if (!(stat & NVM_RD_DIRTY)) {
		nvm_dirty_since = 0;
		nvm_preerased = 0;
		return;
	}
	if (stat & (NVM_RD_DEV_BUSY | NVM_RD_COMMIT_BUSY))
		return;
	if (nvm_dirty_since == 0 || now < nvm_dirty_since) {
		nvm_dirty_since = now;
		nvm_preerase();
		return;
	}
	if (now - nvm_dirty_since >= NVM_DEBOUNCE_NS)
		nvm_commit("dirty");"""),

    ("preerase", """/*
 * The console's idle hook: heartbeat, then commit once the backend has""",
     """/*
