#!/bin/sh
# Issue #419 design prototype: the out-of-context area delta of the capture
# window, by the recipe syn/yosys/ooc.sh uses for KL_nvm_backend
# (sv2v, then `synth_xilinx -family xc7 -flatten`, at the shipped 1x1 and 8x8
# parameter sets, with and without DSP inference). This is a small standalone
# copy of that recipe, not a substitute for the tracked gate: it prices one
# module pair and prints the cell counts, and the implementation still owes
# the tracked ooc.sh row and the post-place delta of section 8.3.
#
# Usage: sh proposal-evidence/area.sh <checkout>
set -eu
R=${1:?usage: area.sh <checkout>}
R=$(cd "$R" && pwd)
H=$(cd "$(dirname "$0")" && pwd)
TMP=$H/build/area
mkdir -p "$TMP"

P1x1="N_STREAM_IN_P=2 N_STREAM_OUT_P=2 N_SPORT_IN_P=1 N_SPORT_OUT_P=1 N_AUDIO_UNIT_P=1 N_CLK_DOM_P=1 N_NAME_P=31"
P8x8="N_STREAM_IN_P=9 N_STREAM_OUT_P=9 N_SPORT_IN_P=8 N_SPORT_OUT_P=8 N_AUDIO_UNIT_P=1 N_CLK_DOM_P=1 N_NAME_P=107"

run() { # <label> <source> <params> <nodsp>
  label=$1; src=$2; params=$3; nodsp=$4
  chp=""
  for kv in $params; do
    chp="$chp chparam -set ${kv%%=*} ${kv##*=} KL_nvm_backend;"
  done
  sv2v --top=KL_nvm_backend "$src" > "$TMP/$label.v"
  yosys -p "read_verilog $TMP/$label.v;$chp synth_xilinx -family xc7$nodsp \
            -top KL_nvm_backend -flatten; stat" > "$TMP/$label.log" 2>&1
  python3 - "$TMP/$label.log" "$label" <<'PY'
import re, sys
text = open(sys.argv[1]).read()
block = text.rsplit("=== KL_nvm_backend ===", 1)[-1]
def n(name):
    m = re.search(r"^\s+(\d+)\s+%s$" % re.escape(name), block, re.M)
    return int(m.group(1)) if m else 0
lut = sum(n("LUT%d" % k) for k in range(1, 7))
lutram = 4 * (n("RAM32M") + n("RAM64M") + n("RAM128X1D")) \
       + 2 * (n("RAM32X1D") + n("RAM64X1D"))
ff = n("FDRE") + n("FDSE") + n("FDCE") + n("FDPE")
print("%-34s LUT=%4d LUTRAM=%4d LUT_TOT=%4d FF=%4d DSP=%2d CARRY4=%3d"
      % (sys.argv[2], lut, lutram, lut + lutram, ff, n("DSP48E1"), n("CARRY4")))
PY
}

printf '== OOC area (synth_xilinx -family xc7 -flatten), KL_nvm_backend ==\n'
for shape in 1x1 8x8; do
  case $shape in 1x1) P=$P1x1 ;; *) P=$P8x8 ;; esac
  for dsp in "" " -nodsp"; do
    tag=$(printf '%s%s' "$shape" "$(test -n "$dsp" && echo -nodsp || true)")
    run "tracked-$tag" "$R/hdl/milan/KL_nvm_backend.sv" "$P" "$dsp"
    run "prototype-$tag" "$H/prototype/KL_nvm_backend.proto.sv" "$P" "$dsp"
  done
done

