        "stand and nothing may retire the blank")),
    "gap-then-close": dict(pre=["--op", "erase0"], mid=["--op", "close0"],
                           want="new", dirty=0, load=True, why=(
        "the same blank span, closed later: the update must reach flash and "
        "dirty must clear")),
    "failed-write": dict(pre=["--op", "fail0", "--op", "write1"], want="old",
                         dirty=1, load=True, why=(
        "an ERASE whose WRITE failed, with another record's completed update "
        "making the image dirty")),
}
#: the triggers the tracked firmware never emits
PROTO_ONLY_TRIGGERS = ("pre-arm", "post-arm")


def case_argv(name: str, out: Path, preload: tuple[str, str]) -> list[str]:
    spec = CASES[name]
    slow = spec.get("slow", False)
    first, second = ("6000", "9000") if slow else ("1500", "4000")
    argv = ["--erase-ms", "3000"] if slow else []
    if spec.get("load"):
        argv += ["--slot-a", preload[0], "--slot-b", preload[1]]
    argv += ["--boot", "--change", "0"]
    argv += spec.get("pre", [])
    for at in spec.get("at", []):
        argv += ["--at", at]
    argv += ["--idle-ms", first, "--snapshot",
             "--dump-ddr", str(out / "ddr-first.bin"),
             "--dump-slot-a", str(out / "slot-a-first.bin"),
             "--dump-slot-b", str(out / "slot-b-first.bin")]
    argv += spec.get("mid", [])
    argv += ["--idle-ms", second, "--snapshot",
             "--dump-ddr", str(out / "ddr-final.bin"),
             "--dump-slot-a", str(out / "slot-a-final.bin"),
             "--dump-slot-b", str(out / "slot-b-final.bin")]
    return argv


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--root", type=Path, required=True)
    ap.add_argument("--only", default="", help="run one co-simulation build")
