    pin = subprocess.check_output(["rtk", "proxy", "git", "rev-parse", "HEAD"],
                                  cwd=root / "protocol-processor", text=True).strip()
    assert pin == PIN, pin
    before = {p: sha((root / p).read_bytes()) for p in PRISTINE}
